      if (playersCounter) playersCounter.textContent = '';
      if (joinUrlEl) joinUrlEl.textContent = '';
      if (overMessage) overMessage.textContent = '';
      clearLeaderboard();
      if (progressEl) progressEl.textContent = 'Question ' + (idx + 1) + ' of ' + total;
      if (bodyEl) bodyEl.textContent = state.question ? state.question.body : '';
      if (state.question && state.question.options) {
        renderOptions(state.question.options, status, answers);
      } else {
        clearOptions();
      }
      if (answersCounter) answersCounter.textContent = 'Answers: ' + answers + ' / ' + players;
      var isLast = !!state.is_last;
      if (status === 'open') {
        setHidden(btnStart, true);
        setHidden(btnFinish, false);
        setHidden(btnNext, true);
        setHidden(btnEnd, true);
      } else {
        setHidden(btnStart, true);
        setHidden(btnFinish, true);
        if (isLast) {
          setHidden(btnNext, true);
          setHidden(btnEnd, false);
        } else {
          setHidden(btnNext, false);
          setHidden(btnEnd, true);
        }
      }
    } else if (status === 'finished') {
      setHidden(viewLobby, true);
      setHidden(viewQuestion, true);
      setHidden(viewOver, false);
      // Populate over message (server renders empty when not finished)
      if (overMessage) overMessage.textContent = 'The quiz is over';
      // Clear hidden lobby/question so hidden text does not linger after end
      if (playersCounter) playersCounter.textContent = '';
      if (joinUrlEl) joinUrlEl.textContent = '';
      if (progressEl) progressEl.textContent = '';
      if (bodyEl) bodyEl.textContent = '';
      clearOptions();
      if (answersCounter) answersCounter.textContent = '';
      // Leaderboard live (winners update without reload)
      if (state.leaderboard) {
        renderLeaderboard(state.leaderboard);
      } else {
        clearLeaderboard();
      }
      setHidden(btnStart, true);
      setHidden(btnFinish, true);
      setHidden(btnNext, true);
      setHidden(btnEnd, true);
    }
  }

  var lastJson = '';
  function poll() {
    fetch(stateUrl, { cache: 'no-store', credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function(resp) {
        if (!resp.ok) throw new Error('bad status ' + resp.status);
        return resp.json();
      })
      .then(function(state) {
        var s = JSON.stringify(state);
        if (s !== lastJson) {
          lastJson = s;
          render(state);
        }
      })
      .catch(function() {
      });
  }

  // Fast polling so big screen follows moderator close to instantly (speed tiebreak fairness)
  setInterval(poll, 200);
  setTimeout(poll, 80);
  poll();
})();
