(function() {
  var root = document.getElementById('screen-root');
  if (!root) return;
  var stateUrl = root.getAttribute('data-state-url');
  var viewLobby = document.getElementById('view-lobby');
  var viewQuestion = document.getElementById('view-question');
  var viewOver = document.getElementById('view-over');
  var playersCounter = document.getElementById('players-counter');
  var answersCounter = document.getElementById('answers-counter');
  var progressEl = document.getElementById('question-progress');
  var bodyEl = document.getElementById('question-body');
  var optionsList = document.getElementById('options-list');
  var overMessage = document.getElementById('over-message');
  var joinUrlEl = document.getElementById('join-url');
  var quizTitleEl = document.getElementById('quiz-title');
  var qrEl = document.getElementById('qr-code');
  var btnStart = document.getElementById('btn-start');
  var btnFinish = document.getElementById('btn-finish');
  var btnNext = document.getElementById('btn-next');
  var btnEnd = document.getElementById('btn-end');
  var leaderboardEl = document.getElementById('leaderboard');
  var btnTop = document.getElementById('btn-top');
  var timerEl = document.getElementById('timer');

  // Timer local countdown: deadline in local ms, last status
  var timerDeadline = null;
  var lastTimerStatus = null;

  // Init deadline from server-rendered data (so countdown ticks before first poll)
  try {
    if (timerEl && !timerEl.hasAttribute('hidden')) {
      var expAttr = timerEl.getAttribute('data-expires-at');
      var remAttr = timerEl.getAttribute('data-remaining-ms');
      if (remAttr !== null && remAttr !== '') {
        var remMs = parseInt(remAttr, 10);
        if (!isNaN(remMs)) {
          timerDeadline = Date.now() + remMs;
          lastTimerStatus = 'open';
        }
      } else if (expAttr) {
        var exp0 = Date.parse(expAttr);
        if (!isNaN(exp0)) {
          timerDeadline = exp0;
          lastTimerStatus = 'open';
        }
      } else {
        lastTimerStatus = 'open';
      }
    }
  } catch (e) {}

  function setHidden(el, hidden) {
    if (!el) return;
    if (hidden) el.setAttribute('hidden', '');
    else el.removeAttribute('hidden');
  }

  function letterFor(i) {
    return String.fromCharCode(65 + i);
  }

  function formatTimer(secs) {
    secs = Math.ceil(secs);
    if (secs < 0) secs = 0;
    var m = Math.floor(secs / 60);
    var s = secs % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function getTimerInfo(state) {
    if (state.timer && typeof state.timer === 'object') {
      return state.timer;
    }
    if (state.timer_text) {
      return {
        text: state.timer_text,
        remaining_ms: state.timer_remaining_ms,
        remaining_seconds: state.timer_remaining_seconds,
        total_seconds: state.timer_total_seconds,
        expires_at: state.timer_expires_at,
        enabled: true
      };
    }
    return null;
  }

  function updateTimerFromState(state) {
    if (!timerEl) return;
    var status = state.status;
    lastTimerStatus = status;
    var info = getTimerInfo(state);
    if (status === 'open' && info && info.text) {
      setHidden(timerEl, false);
      if (info.remaining_ms !== undefined && info.remaining_ms !== null) {
        var r = parseInt(info.remaining_ms, 10);
        if (!isNaN(r)) {
          if (r < 0) r = 0;
          timerDeadline = Date.now() + r;
        }
      } else if (info.remaining_seconds !== undefined && info.remaining_seconds !== null) {
        var rs = parseInt(info.remaining_seconds, 10);
        if (!isNaN(rs)) {
          if (rs < 0) rs = 0;
          timerDeadline = Date.now() + rs * 1000;
        }
      } else if (info.expires_at) {
        var exp = Date.parse(info.expires_at);
        if (!isNaN(exp)) timerDeadline = exp;
      }
      if (timerEl.textContent !== info.text) timerEl.textContent = info.text;
    } else {
      timerDeadline = null;
      if (timerEl.textContent !== '') timerEl.textContent = '';
      setHidden(timerEl, true);
    }
  }

  function tickTimer() {
    if (!timerEl) return;
    if (lastTimerStatus !== 'open' || timerDeadline === null) return;
    if (timerEl.hasAttribute('hidden')) return;
    var rem = timerDeadline - Date.now();
    if (rem < 0) rem = 0;
    var secs = Math.ceil(rem / 1000);
    var txt = formatTimer(secs);
    if (timerEl.textContent !== txt) timerEl.textContent = txt;
  }
  setInterval(tickTimer, 200);

  function clearOptions() {
    if (!optionsList) return;
    while (optionsList.firstChild) optionsList.removeChild(optionsList.firstChild);
    optionsList.classList.remove('stage-options--results');
  }

  function clearLeaderboard() {
    if (!leaderboardEl) return;
    while (leaderboardEl.firstChild) leaderboardEl.removeChild(leaderboardEl.firstChild);
  }

  function clearTimer() {
    if (!timerEl) return;
    timerDeadline = null;
    timerEl.textContent = '';
    setHidden(timerEl, true);
  }

  function renderLeaderboard(list) {
    if (!leaderboardEl) return;
    while (leaderboardEl.firstChild) leaderboardEl.removeChild(leaderboardEl.firstChild);
    (list || []).forEach(function(entry) {
      var li = document.createElement('li');
      li.className = 'leaderboard-item';
      if (entry.id !== undefined && entry.id !== null) li.setAttribute('data-player-id', entry.id);

      var place = document.createElement('span');
      place.className = 'leaderboard__place';
      place.textContent = 'Place ' + entry.place;
      li.appendChild(place);

      var name = document.createElement('span');
      name.className = 'leaderboard__name';
      name.textContent = entry.name;
      li.appendChild(name);

      var pts = document.createElement('span');
      pts.className = 'leaderboard__points';
      pts.textContent = entry.points_text;
      li.appendChild(pts);

      if (entry.is_winner) {
        var mark = document.createElement('span');
        mark.className = 'leaderboard__mark';
        mark.textContent = 'Winner';
        li.appendChild(mark);
      }

      leaderboardEl.appendChild(li);
    });
  }

  function updateTopLabel(state) {
    if (btnTop && state.top_label) {
      if (btnTop.textContent !== state.top_label) btnTop.textContent = state.top_label;
    } else if (btnTop && state.winners_count) {
      var lbl = 'Top ' + state.winners_count;
      if (btnTop.textContent !== lbl) btnTop.textContent = lbl;
    }
  }

  function renderOptions(options, status, answersCount) {
    if (!optionsList) return;
    while (optionsList.firstChild) optionsList.removeChild(optionsList.firstChild);
    var isClosed = (status === 'closed');
    if (isClosed) optionsList.classList.add('stage-options--results');
    else optionsList.classList.remove('stage-options--results');
    var total = answersCount > 0 ? answersCount : 1;
    options.forEach(function(opt, idx) {
      var li = document.createElement('li');
      li.className = 'stage-option' + ((isClosed && opt.correct) ? ' is-correct' : '');
      li.setAttribute('data-option-id', opt.id);

      var bar = document.createElement('span');
      bar.className = 'stage-option__bar';
      var share = 0;
      if (isClosed) {
        var c = opt.count || 0;
        share = (c * 100.0 / total);
      }
      bar.setAttribute('style', '--share: ' + share.toFixed(1) + '%');
      li.appendChild(bar);

      var letter = document.createElement('span');
      letter.className = 'stage-option__letter';
      letter.textContent = letterFor(idx);
      li.appendChild(letter);

      var title = document.createElement('span');
      title.className = 'stage-option__title';
      title.textContent = opt.text;
      li.appendChild(title);

      if (isClosed) {
        var count = document.createElement('span');
        count.className = 'stage-option__count';
        count.textContent = String(opt.count || 0);
        li.appendChild(count);

        if (opt.correct) {
          var mark = document.createElement('span');
          mark.className = 'stage-option__mark';
          mark.textContent = 'Correct';
          li.appendChild(mark);
        }
      }

      optionsList.appendChild(li);
    });
  }

  function render(state) {
    var status = state.status;
    var total = state.total || 0;
    var idx = (state.current_index === null || state.current_index === undefined) ? 0 : state.current_index;
    var players = state.players_count || 0;
    var answers = state.answers_count || 0;

    updateTopLabel(state);
    updateTimerFromState(state);

    if (status === 'waiting') {
      setHidden(viewLobby, false);
      setHidden(viewQuestion, true);
      setHidden(viewOver, true);
      if (playersCounter) playersCounter.textContent = 'Players: ' + players;
      if (progressEl) progressEl.textContent = '';
      if (bodyEl) bodyEl.textContent = '';
      clearOptions();
      if (answersCounter) answersCounter.textContent = '';
      if (overMessage) overMessage.textContent = '';
      clearLeaderboard();
      clearTimer();
      // updateTimer already hid, but ensure cleared text for hidden checks
      lastTimerStatus = status;
      timerDeadline = null;
      setHidden(btnStart, false);
      setHidden(btnFinish, true);
      setHidden(btnNext, true);
      setHidden(btnEnd, true);
    } else if (status === 'open' || status === 'closed') {
      setHidden(viewLobby, true);
      setHidden(viewQuestion, false);
      setHidden(viewOver, true);
      if (playersCounter) playersCounter.textContent = '';
      if (joinUrlEl) joinUrlEl.textContent = '';
      if (overMessage) overMessage.textContent = '';
      clearLeaderboard();
      if (progressEl) progressEl.textContent = 'Question ' + (idx + 1) + ' of ' + total;
      if (bodyEl) bodyEl.textContent = state.question ? state.question.body : '';
      if (state.question && state.question.options) {
        renderOptions(state.question.options, status, answers);
      } else {
        clearOptions();
      }
      if (answersCounter) answersCounter.textContent = 'Answers: ' + answers + ' / ' + players;
      if (status === 'closed') {
        clearTimer();
        lastTimerStatus = status;
      }
      var isLast = !!state.is_last;
      if (status === 'open') {
        setHidden(btnStart, true);
        setHidden(btnFinish, false);
        setHidden(btnNext, true);
        setHidden(btnEnd, true);
      } else {
        setHidden(btnStart, true);
        setHidden(btnFinish, true);
        if (isLast) {
          setHidden(btnNext, true);
          setHidden(btnEnd, false);
        } else {
          setHidden(btnNext, false);
          setHidden(btnEnd, true);
        }
      }
    } else if (status === 'finished') {
      setHidden(viewLobby, true);
      setHidden(viewQuestion, true);
      setHidden(viewOver, false);
      if (overMessage) overMessage.textContent = 'The quiz is over';
      if (playersCounter) playersCounter.textContent = '';
      if (joinUrlEl) joinUrlEl.textContent = '';
      if (progressEl) progressEl.textContent = '';
      if (bodyEl) bodyEl.textContent = '';
      clearOptions();
      if (answersCounter) answersCounter.textContent = '';
      clearTimer();
      lastTimerStatus = status;
      timerDeadline = null;
      if (state.leaderboard) {
        renderLeaderboard(state.leaderboard);
      } else {
        clearLeaderboard();
      }
      setHidden(btnStart, true);
      setHidden(btnFinish, true);
      setHidden(btnNext, true);
      setHidden(btnEnd, true);
    }
  }

  function stateKey(state) {
    // Exclude volatile timer countdown from change detection; timer ticks separately.
    // Keep timer presence (enabled vs disabled) so enabling/disabling triggers render.
    var copy = {};
    for (var k in state) {
      if (!Object.prototype.hasOwnProperty.call(state, k)) continue;
      if (k === 'timer' || k === 'timer_text' || k === 'timer_remaining_ms' || k === 'timer_remaining_seconds' || k === 'timer_expires_at' || k === 'timer_total_seconds') continue;
      copy[k] = state[k];
    }
