  }

  var lastJson = '';
  function poll() {
    fetch(stateUrl, { cache: 'no-store', credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function(resp) {
        if (!resp.ok) throw new Error('bad status ' + resp.status);
        return resp.json();
      })
