<script>
(function() {
  var btn = document.getElementById('add-option');
  var container = document.getElementById('option-rows');
  if (!btn || !container) return;
  btn.addEventListener('click', function() {
    var count = container.querySelectorAll('[data-option-row]').length;
    var nextNum = count + 1;
    var nextIndex = count;
    var div = document.createElement('div');
    div.className = 'option-row';
    div.setAttribute('data-option-row', '');
    // Build row with same structure as server-rendered
    var labelHidden = document.createElement('label');
    labelHidden.className = 'visually-hidden';
    labelHidden.setAttribute('for', 'question_options_attributes_' + nextIndex + '_text');
    labelHidden.textContent = 'Option ' + nextNum;
    var inputText = document.createElement('input');
    inputText.className = 'input';
    inputText.type = 'text';
    inputText.id = 'question_options_attributes_' + nextIndex + '_text';
    inputText.name = 'question[options_attributes][' + nextIndex + '][text]';
    inputText.value = '';
    inputText.placeholder = 'Option ' + nextNum;
    inputText.setAttribute('aria-label', 'Option ' + nextNum);
    inputText.setAttribute('autocomplete', 'off');
    var hidden = document.createElement('input');
    hidden.type = 'hidden';
    hidden.name = 'question[options_attributes][' + nextIndex + '][correct]';
    hidden.value = '0';
    hidden.setAttribute('autocomplete', 'off');
    var labelBox = document.createElement('label');
    labelBox.className = 'checkbox';
    labelBox.setAttribute('for', 'question_options_attributes_' + nextIndex + '_correct');
    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'question_options_attributes_' + nextIndex + '_correct';
    checkbox.name = 'question[options_attributes][' + nextIndex + '][correct]';
    checkbox.value = '1';
    checkbox.setAttribute('aria-label', 'Option ' + nextNum + ' is correct');
    labelBox.appendChild(checkbox);
    labelBox.appendChild(document.createTextNode(' Option ' + nextNum + ' is correct'));
    div.appendChild(labelHidden);
    div.appendChild(inputText);
    div.appendChild(hidden);
    div.appendChild(labelBox);
    container.appendChild(div);
    // Focus new input for convenience
    try { inputText.focus(); } catch (e) {}
  });
})();
</script>
